using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RemainingOcclusion {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string P(Transform t)=>t.parent?P(t.parent)+"/"+t.name:t.name;
 public static object Begin(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||StaticOcclusionCulling.isRunning)throw new Exception("Saved idle Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;if(root.Find("B5_Occlusion_ViewVolumes"))throw new Exception("Already configured");string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_Occlusion_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity");File.Copy(Path.GetFullPath(s.path),backup);var changes=new List<object>();foreach(var mf in root.GetComponentsInChildren<MeshFilter>()){var rr=mf.GetComponent<Renderer>();if(!rr||!rr.enabled)continue;string asset=AssetDatabase.GetAssetPath(mf.sharedMesh);bool shell=mf.name.StartsWith("CF_B5_")&&mf.transform.IsChildOf(root.Find("B5_FullLayout_Implementation/AF_B5_FullLayout"))||asset.EndsWith("TA_VA_Shaft.fbx")||asset.EndsWith("RD_VB_Shaft.fbx")||asset.EndsWith("RD_VL_Shaft.fbx");if(!shell)continue;var old=GameObjectUtility.GetStaticEditorFlags(mf.gameObject);var next=old|StaticEditorFlags.OccluderStatic|StaticEditorFlags.OccludeeStatic;GameObjectUtility.SetStaticEditorFlags(mf.gameObject,next);changes.Add(new{path=P(mf.transform),previous=(int)old,current=(int)next});}
 var data=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/plan.json"));var g=new GameObject("B5_Occlusion_ViewVolumes");g.transform.SetParent(root,false);foreach(var e in (JObject)data["rooms"]){var r=e.Value;var v=new GameObject("View_"+e.Key);v.transform.SetParent(g.transform,false);float height=e.Key.StartsWith("V")?18.8f:3.2f;v.transform.localPosition=new Vector3((float)r["x"],height/2,-(float)r["v"]);var area=v.AddComponent<OcclusionArea>();area.size=new Vector3((float)r["r"]*2, height,(float)r["r"]*2);}
 foreach(var t in data["tunnels"]){var p=new Vector3((float)t["p"][0],1.6f,-(float)t["p"][1]);var q=new Vector3((float)t["q"][0],1.6f,-(float)t["q"][1]);var v=new GameObject("View_"+(string)t["id"]);v.transform.SetParent(g.transform,false);v.transform.localPosition=(p+q)/2;v.transform.localRotation=Quaternion.LookRotation(q-p);var area=v.AddComponent<OcclusionArea>();area.size=new Vector3(4.2f,3.2f,Vector3.Distance(p,q)+1.0f);}
 var result=new{backup,occluders=changes,areas=34,dynamicRenderers=root.GetComponentsInChildren<Renderer>().Count(r=>r.allowOcclusionWhenDynamic),cameras=s.GetRootGameObjects().SelectMany(g0=>g0.GetComponentsInChildren<Camera>(true)).Select(c=>new{path=P(c.transform),c.useOcclusionCulling})};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/occlusion_setup.json",JsonConvert.SerializeObject(result,Formatting.Indented));EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();return new{occluders=changes.Count,areas=34,running=StaticOcclusionCulling.isRunning};}
 public static object Corridors(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||StaticOcclusionCulling.isRunning)throw new Exception("Saved idle Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var changes=new List<object>();foreach(var mf in root.Find("B5_FullLayout_Implementation/AF_B5_FullLayout").GetComponentsInChildren<MeshFilter>()){if(!mf.name.StartsWith("CF_B5-"))continue;var old=GameObjectUtility.GetStaticEditorFlags(mf.gameObject);GameObjectUtility.SetStaticEditorFlags(mf.gameObject,old|StaticEditorFlags.OccluderStatic|StaticEditorFlags.OccludeeStatic);changes.Add(new{path=P(mf.transform),previous=(int)old,current=(int)GameObjectUtility.GetStaticEditorFlags(mf.gameObject)});}File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/occlusion_corridors.json",JsonConvert.SerializeObject(changes,Formatting.Indented));EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);StaticOcclusionCulling.GenerateInBackground();return new{corridorOccluders=changes.Count,running=StaticOcclusionCulling.isRunning};}
 public static object Status(){var result=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize};if(!result.running){var s=SceneManager.GetActiveScene();if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/occlusion_result.json",JsonConvert.SerializeObject(result,Formatting.Indented));}return result;}
}
